import os
import requests
from typing import Any, Dict, List, Optional


ELEVENLABS_API_BASE = "https://api.elevenlabs.io/v1"


def _headers() -> Dict[str, str]:
    api_key = os.getenv("ELEVENLABS_API_KEY")
    if not api_key:
        raise EnvironmentError("ELEVENLABS_API_KEY is required")
    return {
        "xi-api-key": api_key,
        "Content-Type": "application/json",
    }


def list_voices() -> List[Dict[str, Any]]:
    response = requests.get(f"{ELEVENLABS_API_BASE}/voices", headers=_headers(), timeout=30)
    response.raise_for_status()
    data = response.json()
    return data.get("voices", [])


def _voice_matches_locale(voice: Dict[str, Any], target_locale: str) -> bool:
    target = target_locale.lower().replace("_", "-")
    labels = []

    for key in ("labels", "fine_tuning", "metadata"):
        value = voice.get(key)
        if isinstance(value, dict):
            labels.extend(f"{k}:{v}" for k, v in value.items())

    voice_id = str(voice.get("voice_id", "")).lower()
    name = str(voice.get("name", "")).lower()
    preview = str(voice.get("preview_url", "")).lower()

    haystack = " ".join(labels + [voice_id, name, preview])
    return target in haystack


def select_voice_for_locale(target_locale: str, voices: Optional[List[Dict[str, Any]]] = None) -> Optional[Dict[str, Any]]:
    if voices is None:
        voices = list_voices()

    exact = []
    partial = []

    target = target_locale.lower().replace("_", "-")

    for voice in voices:
        if _voice_matches_locale(voice, target):
            exact.append(voice)
        else:
            name = str(voice.get("name", "")).lower()
            if target.split("-")[0] in name:
                partial.append(voice)

    return exact[0] if exact else (partial[0] if partial else None)


def choose_voice_name_for_locale(target_locale: str) -> str:
    voice = select_voice_for_locale(target_locale)
    if not voice:
        raise LookupError(f"No voice found for locale: {target_locale}")
    return str(voice.get("name", ""))


if __name__ == "__main__":
    locale = os.getenv("TARGET_LOCALE", "en-US")
    voice = select_voice_for_locale(locale)
    if voice:
        print(voice.get("name"))
    else:
        print(f"No voice found for locale: {locale}")
